import assert from 'node:assert/strict'

export const readingFresh=[]
const add=(skill,difficulty,passage,prompt,correct,wrong,explanation)=>readingFresh.push({skill,difficulty,passage,prompt,correct,wrong,explanation})
const vocab=(d,p,c,w,e)=>add('Words in Context',d,p,'As used in the text, what does the underlined word most nearly mean?',c,w,e)
const structure=(d,p,task,c,w,e)=>add('Text Structure and Purpose',d,p,task,c,w,e)
const central=(d,p,c,w,e)=>add('Central Ideas and Details',d,p,'Which choice best states the main idea of the text?',c,w,e)
const infer=(d,p,c,w,e)=>add('Inferences',d,p,'Which choice is most logically supported by the text?',c,w,e)
const evidence=(d,p,task,c,w,e)=>add('Command of Evidence (Textual)',d,p,task,c,w,e)
const cross=(d,p,task,c,w,e)=>add('Cross-Text Connections',d,p,task,c,w,e)
const transition=(d,p,c,w,e)=>add('Transitions',d,p,'Which choice completes the text with the most logical transition?',c,w,e)
const synthesis=(d,p,task,c,w,e)=>add('Rhetorical Synthesis',d,p,task,c,w,e)

vocab('medium','In an original story, the arrival of a second messenger does little to _diminish_ Rina’s uncertainty. Although his account agrees with the first messenger’s in several details, he admits that he heard it from her rather than witnessing the event himself. Rina therefore still has only one independent account.','Reduce',['Explain','Publicize','Prolong'],'The second account does not reduce uncertainty because it depends on the first. Prolong would mean extend its duration, which is not the stated function of diminish.')
vocab('hard','A fictional study describes the relationship between two neighborhood repair groups as _reciprocal_. Each lends tools that the other lacks, and each occasionally provides a workspace when the other’s room is unavailable. The arrangement is not a service delivered permanently in only one direction.','Mutual',['Mathematically inverted','Unplanned','Competitive'],'The examples show assistance in both directions. Reciprocal describes mutual exchange rather than a numerical inverse or competition.')
vocab('hard','In a hypothetical planning exercise, a drainage problem initially appears _intractable_: every proposed channel would flood another part of the site. The planners make progress only after changing the assumption that all water must leave through one outlet. The description concerns difficulty under the original constraints.','Difficult to solve',['Impossible to observe','Already resolved','Insignificant'],'The problem resists the initial attempts at a solution. Later progress does not contradict calling it difficult under the original assumptions.')
vocab('medium','A fictional critic writes that the first notes of a film’s closing music _evoke_ the opening scene. The tune is not an exact repetition, but its rhythm brings that earlier encounter to mind before any image from the scene reappears. The connection depends on the listener’s memory.','Call to mind',['Copy exactly','Provide proof of','Erase'],'The music recalls an earlier scene without reproducing it exactly. Evoke concerns an association in memory, not proof that the scenes are identical.')
vocab('hard','In this original story, a theater manager makes a _provision_ for sudden rain by reserving an indoor room near the outdoor stage. The reservation may never be used, but it allows the performance to continue if the weather changes. The word names an arrangement rather than a supply of food.','Preparatory arrangement',['Formal prediction','Purchase of equipment','Public announcement'],'Reserving a room is an arrangement for a possible need. It does not predict that rain will occur or imply that new equipment is bought.')
vocab('medium','In a hypothetical agreement, the team’s permission to enter a cave is _contingent_ on completing a safety course. Approval is not automatic: members who do not finish the course cannot enter, even if they have already paid for transport. The requirement connects access to a stated condition.','Dependent',['Accidental','Immediate','Permanent'],'The safety course is a condition of entry. Contingent on therefore means dependent on, not accidental in this context.')
vocab('hard','In a fictional listening exercise, a conductor asks students to _discern_ a second melody beneath a louder one. At first they hear only a dense mass of sound. After several repetitions, they can follow the quieter line separately without changing the recording’s volume.','Perceive distinctly',['Invent','Perform aloud','Make louder'],'The students come to distinguish an existing musical line. They neither create it nor change the recording.')
vocab('medium','A fictional editor shortens an essay but _retains_ a brief exchange between two speakers. Removing that exchange would make the narrator’s later response seem unmotivated. The editor changes several surrounding paragraphs while deciding that this particular passage must remain.','Keeps',['Memorizes','Pays for','Reconstructs'],'The exchange stays in the edited text. Retains concerns keeping it, not committing it to memory or recreating missing wording.')

structure('hard','A hypothetical researcher argues that a flock’s coordinated turn need not be planned by a leader. She describes a model in which each simulated bird adjusts to a few nearby birds. _The model produces an organized turn even though no individual receives a map of the flock’s overall motion._ She proposes testing which local signals real birds use.','What is the main function of the underlined sentence?','It shows how the model demonstrates the possibility introduced in the first sentence.',['It proves that real birds use exactly the modeled signals.','It identifies the bird that planned the turn.','It establishes that local adjustments prevent coordination.'],'The model supplies an example of coordination without central planning. It motivates, rather than replaces, empirical testing of real signals.')
structure('medium','In an original story, a village council asks a child to name a new lane. She suggests the name of the stream it replaced. Adults debate names honoring people who paid for construction, but walkers soon begin using the child’s suggestion without an official decision. The narrator ends by showing the stream’s name on a handwritten delivery label.','What is the main effect of the final detail?','It shows the suggested name acquiring a practical life beyond the formal debate.',['It establishes that the council unanimously approved the name.','It explains who financed every part of construction.','It demonstrates that the lane remains unusable for deliveries.'],'The delivery label shows actual use despite the unresolved official discussion. It does not supply a formal vote or a financing history.')
structure('hard','A fictional essay begins by describing a dictionary as a record of established usage. It then discusses a new word used consistently within a small group but absent from the dictionary’s latest edition. The author concludes that publication is a delayed record of usage, not the event that first makes usage possible.','Which choice best describes the structure of the text?','It introduces a description, considers a case that clarifies its limits, and distinguishes recording a practice from creating it.',['It presents a dictionary entry and proves no one has used the word.','It traces every edition of one dictionary in chronological order.','It rejects all records of language because they are printed.'],'The unlisted but used word separates social use from later documentation. The argument qualifies the role of dictionaries without rejecting them entirely.')
structure('medium','A hypothetical study tests a flexible joint under repeated bending at a constant rate. The joint survives the trial. _In use, however, the joint would alternate between long rests and sudden bends._ The researchers recommend a second test reflecting those cycles before estimating its working lifetime.','What is the function of the underlined sentence?','It identifies a relevant difference between the trial and the intended operating pattern.',['It shows that the original joint broke during the trial.','It explains why flexibility cannot be measured.','It confirms that the first test reproduced every intended condition.'],'The sentence introduces a different pattern of stress, motivating additional testing without negating the original survival result.')
structure('hard','In this original poem, a speaker watches laundry in a courtyard.\n\nThe shirts all pull toward the street;\nthe ropes insist that they remain.\nI see the wind in what it moves,\nthe boundary in what comes back.\n\nThe poem describes invisible forces through the different effects they have on familiar objects.','What is the main purpose of the text?','To make opposing forces perceptible through the movement and restraint of ordinary objects',['To explain the procedure for washing a shirt','To suggest that the ropes are moving freely down the street','To establish that the courtyard contains no wind'],'The shirts reveal wind through motion and the ropes through restraint. The poem presents observation, not laundering instructions or a literal escape.')
structure('medium','A fictional critic notes that a comic strip gives readers the same sentence in two successive panels. In the first, the speaker confidently predicts an event. In the second, the event has happened in the opposite way, and another character repeats the words. The critic argues that the repeated wording becomes a reply rather than a prediction.','How does the comparison of the two panels develop the text’s claim?','It shows the same wording performing a different function after circumstances change.',['It demonstrates that every panel contains identical events.','It identifies a spelling error that causes the prediction to fail.','It argues that comic strips cannot convey replies without changing words.'],'Context changes the sentence’s role from prediction to a response to its failure. No spelling error or universal limitation is described.')
structure('hard','A hypothetical report describes a voting method that selects the option receiving the most first-place rankings. It then considers a case in which that option is ranked last by most remaining voters. The report uses the case to distinguish having the largest first-choice group from being broadly acceptable across the whole group.','What is the role of the case described in the text?','It illustrates why one measure of preference need not capture a different kind of support.',['It proves that first-place rankings cannot be counted.','It establishes that the winning option received no first-place votes.','It shows that all preference measures necessarily select the same option.'],'The case separates plurality of first choices from broad acceptability. It does not make counting impossible or claim the measures always agree.')
structure('medium','In an original story, a new apprentice is embarrassed when her first woven border is uneven. The instructor places it beside a much older cloth with a similar irregularity, then asks her to identify where each weaver changed direction. He postpones judging which cloth is better until they have examined what the irregularities reveal.','What is the main purpose of the instructor’s comparison?','To turn an apparent flaw into something that can be examined for information about the making process',['To prove the apprentice deliberately copied the older cloth','To show that direction changes are impossible in weaving','To declare that every uneven border is superior to an even one'],'The comparison invites investigation before evaluation. It does not establish copying or a universal aesthetic ranking.')

central('hard','A fictional essayist describes a neighborhood in which one square has three commonly used names. Children use the name of a playground, vendors the name of a former market, and officials the name on the street sign. The essayist treats these names as evidence of different relationships to the same place rather than as mistakes awaiting correction.','Different names for one place can express different histories and uses of it.',['Only the official name can convey meaningful information.','The three groups are referring to three physically separate squares.','The essayist proposes replacing every name with a number.'],'The names correspond to social relationships and remembered uses. The essay does not treat the groups as confused about the location.')
central('medium','In this original story, a witness begins an account with the words “I am certain.” As neighbors ask which details she actually saw, she replaces several assertions with careful distinctions between seeing, hearing, and guessing. By the end she speaks less confidently but can explain the basis of each remaining claim. The narrator presents the revision as a gain in precision.','Greater care about the basis of a claim can improve an account while reducing its apparent certainty.',['The witness becomes more accurate by insisting that every guess was directly observed.','The neighbors persuade the witness to forget everything she saw.','The narrator equates confidence with complete knowledge.'],'The account becomes more qualified and more precise. Reduced certainty is presented as part of improvement rather than as wholesale loss of memory.')
central('hard','In a hypothetical study of a shared task, individuals follow a simple rule: each begins when two nearby participants begin. Changing where the first few participants stand produces large differences in how widely the activity spreads. The researchers argue that the arrangement of contacts matters in addition to the rule followed by each person.','A shared individual rule can produce different group outcomes when patterns of contact differ.',['The participants change their rule every time someone moves.','The study shows that group arrangement has no effect.','Every participant receives instructions describing the entire group’s final behavior.'],'The rule stays fixed while initial arrangement changes spread. This supports the role of interaction structure, not individualized central instructions.')
central('medium','A fictional critic describes a silent comedy in which a character proudly displays a letter to the audience while hiding it from another character. The viewers already know that the letter contains the opposite of what he claims. Their knowledge turns his confident gestures into a source of humor, although the other character remains impressed.','The humor depends on a difference between what the audience knows and what a character believes.',['The audience and every character interpret the letter identically.','The comedy requires the letter’s contents to be unknown to viewers.','The proud character reads the letter aloud to explain its meaning.'],'The audience’s advance knowledge makes the confident display ironic. The impressed character’s limited knowledge sustains the contrast.')
central('hard','In this original poem, a speaker walks along the shore.\n\nThe weed lies higher than the foam.\nIt marks a reach the water made,\nnot where the next wave means to stop.\nI follow what the sea has left\nand keep my footprints farther back.\n\nThe speaker uses traces of earlier water levels while recognizing that they do not determine the next wave.','Evidence of a past event can guide caution without fixing exactly what will happen next.',['Recognizing a past pattern allows the speaker to predict precisely where each new wave will stop.','The speaker chooses intuition over physical evidence when deciding where to walk.','Caution requires permanently avoiding every place that water has ever reached.'],'The weed marks a previous reach, while the speaker explicitly separates that trace from a prediction of the next wave. The other choices add precision, reject the evidence used, or turn local caution into an absolute rule.')
central('medium','A hypothetical experiment compares the shape of a thin sheet before and after it is cut. The cut releases internal tension and the sheet curls. Researchers had previously measured the original flat sheet without noticing the tension. They argue that the response to an intervention can reveal a property not apparent from an undisturbed object’s appearance.','Changing an object’s condition can reveal a hidden property of its earlier state.',['The sheet had no internal tension until after it curled.','A flat appearance always proves that no forces are present.','The cut allows the researchers to recover the sheet’s manufacturing date.'],'Curling after release supplies evidence of prior tension. The main idea concerns information gained through intervention, not appearance alone or historical dating.')
central('hard','A fictional researcher studies an informal exchange network in which people lend items without assigning each loan a price. Participants remember who has helped them but often return help in a different form. The researcher argues that the absence of prices does not mean the absence of accounting; obligations are tracked through relationships rather than through a single numerical ledger.','An exchange system can track obligations through social relationships without pricing every transaction.',['Participants forget every loan as soon as it is made.','Only a numerical price can create any expectation of return.','Every favor is repaid with an identical object immediately.'],'The reported memory of help supports relational accounting. The passage distinguishes a method of tracking from the presence or absence of all obligation.')
central('medium','In an original story, a young actor prepares a scene by memorizing where each object stands. During rehearsal, the director removes one chair. The actor initially stops, then discovers a different movement that preserves the character’s intention. The director praises the adaptation, explaining that the arrangement was a means of expressing the scene rather than its ultimate purpose.','Understanding a purpose can help a performer adapt when a familiar arrangement changes.',['The actor succeeds only by returning the missing chair to its original place.','The director believes objects can never contribute to a performance.','Memorizing positions guarantees successful adaptation without interpretation.'],'The actor preserves intention through changed movement. The arrangement has a role but is not treated as the goal itself.')

infer('hard','In a hypothetical study, a group member can see every other participant’s final choice but not the reasons behind it. Many participants choose the same unfamiliar option because they each assume the others know something they do not. Interviews later reveal that none had independent information favoring it.','Agreement among the participants need not indicate multiple independent sources of support for the option.',['Every participant independently verified that the option was best.','The shared choice proves that the option was objectively the worst.','Participants had direct access to one another’s private reasons.'],'The agreement arose through assumptions about others’ knowledge. It does not establish the option’s quality or independent corroboration.')
infer('medium','In this original story, Ivo rehearses a joke before visiting an old friend. When they meet, the friend quietly mentions a difficult week. Ivo puts away the card on which he wrote the joke and asks about her journey instead. Later, walking home, he finds that he still remembers every word he had prepared.','Ivo’s decision not to tell the joke is more consistent with adjusting to the encounter than with forgetting it.',['Ivo is unable to remember the joke at the meeting or afterward.','The friend explicitly asks Ivo to read from his card.','Ivo decides never to speak humorously to anyone again.'],'The changed conversation and retained memory support adaptation rather than forgetting. The story does not establish a permanent rejection of humor.')
infer('hard','A hypothetical researcher records that one rare action follows another rare event in a small set of observations. She then searches a much larger record and finds many instances of the event without the action. She retains the original observations but narrows her proposed rule from “the event always produces the action” to a conditional claim requiring further investigation.','The larger record supplies counterexamples to the universal rule without making the original co-occurrences impossible.',['The original event-action pairs must have been fabricated.','The event is proven never to influence the action under any conditions.','The larger record confirms that every event is followed by the action.'],'Exceptions disprove the always formulation, while particular co-occurrences can remain real. The effect under other conditions is still unresolved.')
infer('medium','In a fictional discussion, a student correctly follows a sequence of instructions but cannot explain why changing their order would alter the result. A second student works more slowly yet predicts which rearrangements will fail. The instructor evaluates successful execution and understanding of dependencies separately.','Completing one prescribed sequence does not by itself establish the same understanding shown by predicting the effects of rearrangement.',['The first student failed to follow the original sequence.','The slower student cannot perform any part of the task.','The instructor considers successful execution irrelevant.'],'The two observations concern different capacities. Evaluating them separately does not deny the first student’s demonstrated success.')
infer('hard','A hypothetical survey finds that almost everyone recognizes a symbol when it appears beside its usual label. When the same symbol is shown alone, recognition is much lower. The original report had used the labeled condition to claim that the symbol could guide users even when words were unavailable.','The labeled result does not directly demonstrate the symbol’s effectiveness without verbal support.',['The symbol’s appearance necessarily changes when its label is removed.','No participant recognizes the symbol in either condition.','Verbal labels reduce recognition in the reported study.'],'The weaker isolated result exposes reliance on the combined display. It does not imply zero recognition or a changed symbol.')
infer('medium','In this original poem, the speaker addresses a distant friend.\n\nI tell you where the swallows turn,\nthe color of the morning bread.\nThe thing I meant to write stays out;\nits edges gather in the words\nI choose to send instead.','The speaker may communicate something indirectly through the details selected while withholding a direct statement.',['The speaker has written no words at all.','Every detail explicitly names the withheld subject.','The friend is physically present beside the speaker.'],'The withheld thought shapes the surrounding words. The poem suggests indirect expression without revealing the exact subject or the friend’s location beyond distance.')
infer('hard','A hypothetical team trains a classifier using examples labeled by one group of reviewers. On new examples, the classifier agrees with that group but differs systematically from another group using a different definition of the categories. The team notes that agreement with training labels does not settle which definition is appropriate for the intended use.','A high agreement score can depend on the category definition chosen as the reference.',['Both reviewer groups necessarily use identical definitions.','The classifier has been shown to agree equally with both groups.','The first group’s definition is proven appropriate for every purpose.'],'The reference definition affects evaluation. Agreement with one labeling convention does not independently justify choosing it.')
infer('medium','In an original story, a teacher invites a student to teach a familiar game to younger children. The student begins with a strategy but stops when the children ask what counts as a legal move. She rewrites her explanation to begin with rules she had long stopped noticing.','Explaining the game to newcomers makes some assumed knowledge visible to the student.',['The student had never played the game before.','The children already understand every legal move.','The student abandons all explanation after the first question.'],'The children’s question reveals a prerequisite omitted from the initial explanation. Revising the order is consistent with recognizing an assumption.')

evidence('hard','In a hypothetical study, a researcher proposes that a bird identifies a call by the relative timing of its notes rather than by their absolute pitch. Recordings can be altered to shift every note upward together while preserving the timing, or to change timing while keeping the original pitches.','Which finding, if true, would most directly support the proposal?','Birds respond similarly after the uniform pitch shift but respond differently when the relative timing changes.',['Birds can hear the original recording at close range.','Both altered recordings contain the same number of notes.','Some recordings are louder than others before standardization.'],'The contrasting manipulations distinguish the proposed timing cue from absolute pitch. Audibility and note count alone do not show which cue controls identification.')
evidence('medium','A fictional researcher claims that a discussion method helps participants notice disagreements they previously expressed in different words. She distinguishes identifying a genuine difference in claims from simply counting how often people interrupt. Groups receive the same discussion time with or without the method.','Which finding, if true, would most directly support the claim?','Participants using the method more accurately identify incompatible claims in a later transcript analysis.',['Participants using the method speak for more total minutes.','The discussion room contains the same number of chairs.','Some participants prefer written invitations to spoken ones.'],'Identifying incompatible claims directly addresses the stated outcome. Speaking time and physical arrangements do not demonstrate recognition of disagreement.')
evidence('hard','A hypothetical researcher argues that a pattern in a sequence helps people predict its next element because they learn the relation between neighboring elements. An alternative explanation is that they memorize the particular sequence. She tests new sequences that preserve the relation but use different elements.','Which finding, if true, would most directly support the relational-learning explanation?','Participants predict new sequences following the relation more accurately than equally unfamiliar sequences that violate it.',['Participants can recognize the first sequence’s exact printed appearance.','The new elements are displayed in the same font size.','Some participants recall having seen patterns in other tasks.'],'Successful transfer specific to the preserved relation goes beyond memorizing the original elements. Recognition of the original alone would fit the alternative.')
evidence('medium','A fictional researcher proposes that a play’s recurring knock at a door changes meaning as the audience learns more about the visitor. She seeks a quotation from a fictional performance review that connects an unchanged sound to a changed audience interpretation, rather than to a louder or faster performance.','Which quotation would most directly support the proposal?','“The same three taps that first promised rescue now announced the person the audience had learned to fear.”',['“The actor struck the door so loudly in the final scene that the audience covered its ears.”','“The door had been painted a different color before the company’s second performance.”','“Several spectators remembered the theater’s entrance rather than the door on the stage.”'],'The identical taps acquire a different significance through knowledge of the visitor. A changed sound or unrelated physical detail would not show the proposed effect.')
evidence('hard','A hypothetical researcher attributes a change in a liquid’s measured clarity entirely to the removal of suspended particles. The treatment also changes the liquid’s color, which may influence the instrument. Another team uses an independent particle count and tests colored liquids with unchanged particle concentrations.','Which finding, if true, would most directly weaken the explanation?','Particle counts remain stable, while the instrument reports greater clarity when only the color is changed.',['The instrument displays a number for each tested sample.','The team stores untreated samples in identical containers.','Some particles are visible under a microscope before treatment.'],'The independent count and color-only manipulation challenge the exclusive particle-removal account. Basic measurability and initial particle presence do not distinguish it.')
evidence('medium','A fictional researcher claims that longer turns in a group conversation show that more participants are contributing ideas. She measures turn duration but has not counted distinct speakers. A follow-up records both measures using the same definition of a turn as the original study.','Which finding, if true, would most directly weaken the claim?','Average turn length increases because one speaker talks longer, while fewer distinct participants contribute.',['The conversations are recorded with the same equipment.','Some turns contain questions instead of statements.','The researcher can measure every turn’s duration in seconds.'],'Longer turns can accompany less participation, directly challenging the inference from duration to broader contribution. The other facts do not address breadth.')
evidence('hard','A hypothetical researcher proposes that a species chooses nesting sites solely according to entrance size. In the observed sample, larger entrances also face away from prevailing winds. A follow-up varies entrance size and orientation separately while keeping other relevant features similar.','Which finding, if true, would most directly weaken the proposal?','Site choice follows orientation when it conflicts with entrance size, and size alone produces no consistent preference.',['The researchers measure each entrance before recording its orientation.','The species uses more than one nesting site.','Some entrances are larger than others in the original sample.'],'The separate manipulation supports an alternative cue over the proposed sole determinant. Variation in the original sample does not isolate either feature.')
evidence('medium','A fictional scholar argues that an original novel presents apology as requiring attention to the injured person rather than merely a polished speech. She seeks a quotation showing a character changing what he does in response to another person’s account, rather than repeating a prepared explanation.','Which quotation would most directly support the interpretation?','“He folded the speech he had practiced and asked which promise she needed him to keep now.”',['“He repeated the speech more loudly when she asked him to explain the first sentence.”','“He admired the careful handwriting of the apology after she had left the room.”','“He had chosen the paper for the apology several days before their meeting.”'],'The character sets aside a prepared performance and attends to the other person’s present need. The alternatives emphasize delivery or presentation without that response.')

cross('hard','Text 1\nA fictional researcher interprets a group’s unanimous public vote as evidence that every member privately prefers the selected option.\n\nText 2\nAnother researcher observes that members hear earlier votes before announcing their own. Some may follow an apparent consensus despite private doubts. She recommends collecting initial preferences independently before treating unanimity as evidence of identical private views.','What assumption in Text 1 does Text 2 most directly question?','That agreement in publicly expressed choices necessarily reflects agreement in private preferences',['That a public vote can be counted','That the group selected an option','That members can hear spoken responses'],'Sequential influence can align public votes without aligning initial private views. Text 2 questions interpretation of unanimity, not the vote’s existence.')
cross('medium','Text 1\nA fictional poet values a translation that preserves a poem’s abrupt ending, even if the final sentence sounds unusual in the new language.\n\nText 2\nAnother poet also considers the abrupt ending important but uses different syntax to make it sound intentionally unfinished rather than accidentally ungrammatical. She distinguishes preserving an effect from preserving the exact order of words.','On which point would both poets most likely agree?','The ending’s abruptness is a feature worth considering in translation.',['The original word order must always remain unchanged.','An unfinished effect is necessarily an accidental error.','Every unusual sentence should be removed from a translation.'],'Both value the ending’s effect. They differ over how to recreate it in another language, not whether it matters.')
cross('hard','Text 1\nA hypothetical analyst says that a prediction system is useful whenever it correctly identifies most of the events it flags.\n\nText 2\nAnother analyst notes that such a system could flag only a small fraction of the events that actually occur. She recommends also reporting how many real events are missed, especially when missing one is costly.','What does Text 2 add to the evaluation proposed in Text 1?','The proportion of actual events that the system fails to flag',['Only the percentage of flags that are correct','The number of words in the system’s title','The requirement that the system issue no flags at all'],'The second analyst adds missed-event coverage to correctness among flags. These are different conditional outcomes.')
cross('medium','Text 1\nA fictional critic admires a documentary for presenting speakers’ statements without an audible narrator, which she describes as removing the filmmaker’s interpretation.\n\nText 2\nAnother critic notes that the filmmaker still chooses which statements to include and where to place them. The absence of narration, he argues, changes how interpretation is conveyed without eliminating those editorial choices.','How does Text 2 qualify Text 1’s assessment?','It identifies forms of selection and arrangement that can convey interpretation without narration.',['It proves that none of the speakers made the recorded statements.','It claims that every documentary must include an audible narrator.','It establishes that the statements appear in a randomly chosen order.'],'Editorial selection can remain influential without an added voice. Text 2 does not deny authenticity or demand a particular technique.')
cross('hard','Text 1\nA hypothetical researcher concludes that a group has no knowledge of a route because its members cannot describe it verbally.\n\nText 2\nAnother researcher asks the members to travel the route. They reach the destination reliably but struggle to name the turns. She distinguishes successful navigation from an explicit verbal description of it.','Which distinction is central to Text 2’s response?','Knowing how to perform an activity can differ from being able to explain it in words.',['A verbal description always guarantees successful navigation.','The members reach different destinations on every attempt.','Route knowledge can exist only as a list of street names.'],'Performance supplies evidence of practical knowledge absent from the verbal test. It does not establish that either ability always implies the other.')
cross('medium','Text 1\nA fictional designer wants a board game to reward players who plan several moves ahead. She proposes testing whether outcomes depend on those plans.\n\nText 2\nAnother designer agrees but notes that an occasional random event can make a strong plan fail. He recommends evaluating performance across many games rather than treating a single loss as proof that planning has no value.','On which point would both designers most likely agree?','The role of planning in outcomes is relevant to evaluating the game.',['One random event proves all planning is useless.','The game must produce identical outcomes on every play.','A player’s final result should never be examined.'],'Both consider planning relevant; the second qualifies how much evidence a single game provides.')
cross('hard','Text 1\nA fictional historian treats the first surviving written mention of a custom as the date when the custom began.\n\nText 2\nAnother historian notes that the document describes the custom as already familiar and gives no account of its introduction. She treats the document as evidence that the custom existed by that date, while leaving its beginning unresolved.','How does Text 2 revise the inference in Text 1?','It treats the date as an upper bound on the custom’s possible starting date rather than its exact starting date.',['It proves that the custom began after the document was written.','It identifies an exact earlier starting date.','It denies that the document provides evidence of the custom’s existence.'],'The mention establishes presence by that date, not necessarily origin on that date. Familiarity suggests prior use without fixing its exact duration.')
cross('medium','Text 1\nA hypothetical researcher evaluates a communication system by whether messages arrive intact. She treats successful delivery as successful communication.\n\nText 2\nAnother researcher observes that recipients may interpret an intact message differently when they lack the sender’s background knowledge. She recommends testing what recipients understand as well as whether the text arrives unchanged.','What limitation of Text 1’s measure does Text 2 identify?','Preserving a message’s form does not by itself establish that its intended meaning is understood.',['An intact message necessarily has no meaning.','Recipients always possess identical background knowledge.','Transmission accuracy cannot be tested.'],'Text 2 separates delivery fidelity from understanding. It retains the relevance of intact transmission but adds an outcome it does not guarantee.')

transition('medium','In a fictional study, researchers call a judgment “reversible” when a participant can revise it after receiving new information. The term does not mean that the original decision is forgotten. ______, it means the decision remains open to reconsideration rather than being treated as final.','In other words',['Nevertheless','For example','Meanwhile'],'The final sentence restates the definition more directly. It does not offer a separate example or introduce a contrasting outcome.')
transition('medium','In a fictional town, the local paper announced a storytelling festival and described its broad aim of bringing generations together. The next paragraph identified one planned activity. ______, children would interview older residents and perform short scenes based on the resulting accounts.','Specifically',['Instead','As a result','On the contrary'],'The activity supplies a particular detail of the announced plan. It is not a consequence already observed, a replacement, or a contradiction.')
transition('hard','In a hypothetical comparison, both groups heard the same instructions and had equal time to practice. The researcher had predicted that an added visual cue would improve recall. The cue group, however, remembered fewer steps than the other group. ______, the observed result did not support the prediction.','Therefore',['For example','Previously','Similarly'],'The final assessment follows from the reported result. The preceding comparison is the evidence for the conclusion, not a separate illustration of it.')
transition('medium','A fictional novelist drafts a chapter in which a traveler repairs a boat on one shore of a lake. Another character’s actions occur during that same hour on the opposite shore. ______, the traveler’s sister is gathering the people who will help launch it when the repairs are finished.','Meanwhile',['Consequently','Instead','For instance'],'The passage explicitly introduces simultaneous action elsewhere. It does not say that repairing the boat causes the sister’s action or that she replaces the traveler.')
transition('hard','A hypothetical report defines a successful search as finding an item, then evaluates a new method using that definition. The method finds more items but damages many of them during retrieval. ______, the authors acknowledge that their success measure omits an outcome important to anyone hoping to use what is found.','Accordingly',['By comparison','For example','Earlier'],'Acknowledging the limitation follows from damage being excluded by the definition. The sentence draws an implication rather than adding a second method or earlier event.')
transition('medium','In an original story, a young runner’s shoes split just before a race. She borrows a pair that fits poorly and worries that she will have to stop. ______, she completes the course, accepting a slower pace so that she can keep her footing.','Nevertheless',['Consequently','For example','Likewise'],'Finishing contrasts with the obstacle and expectation of stopping. Poor fit does not itself cause successful completion, and no parallel example precedes it.')
transition('medium','A fictional researcher values a set of interviews because participants describe how they learned their work. The accounts also identify the people from whom they sought help. ______, several include drawings showing the arrangement of equipment in rooms that no longer survive.','Furthermore',['In contrast','As a result','Instead'],'The drawings supply another reason the interviews are valuable. They are additional information, not a consequence of naming helpers or an opposing feature.')
transition('hard','In a hypothetical experiment, participants could copy the solution displayed beside each practice problem. The final assessment removed the displayed solutions, requiring participants to work independently. ______, high scores during practice alone could not establish how well participants would perform on the assessment.','For this reason',['In the same way','For example','At the same time'],'The change in available support explains why practice scores alone are insufficient. The final sentence is an inference from that difference, not another example or simultaneous event.')

synthesis('medium','A student is researching a fictional craft workshop and has taken these notes:\n\n- The workshop calls one technique “fold-stamping.”\n- Workers fold a sheet before pressing pigment onto its raised edges.\n- When the sheet is opened, the folds produce a repeated pattern.\n- The workshop also teaches freehand painting.','The student wants to explain the term “fold-stamping” to readers unfamiliar with it. Which choice most effectively uses relevant information from the notes to accomplish this goal?','Fold-stamping creates a repeated pattern by pressing pigment onto the raised edges of a folded sheet and then opening it.',['The workshop teaches both fold-stamping and freehand painting.','Workers at the workshop use pigment when they make patterns.','Freehand painting is another technique taught at the workshop.'],'The correct choice explains both the process and its named result. The alternatives list activities or mention materials without defining the term.')
synthesis('medium','A student is researching a fictional traveling exhibition and has taken these notes:\n\n- The exhibition opened in Bellmere in April.\n- It moved to Orin in June.\n- It reached Tavil in September.\n- Each host city provided a different performance space.','The student wants to describe the sequence of cities visited. Which choice most effectively uses relevant information from the notes to accomplish this goal?','After opening in Bellmere in April, the exhibition moved to Orin in June and Tavil in September.',['Each city provided a different performance space for the traveling exhibition.','The exhibition visited three cities, each of which hosted performances.','Tavil hosted the exhibition in September, several months after its opening.'],'The correct choice gives all three cities in chronological order. The other choices omit part or all of the requested sequence.')
synthesis('hard','A student is researching a fictional illustrator, Eda Neris, and has taken these notes:\n\n- Neris trained as a botanist.\n- She later illustrated a collection of folktales.\n- Her illustrations use branching diagrams to show relationships among characters.\n- The collection contains stories from six regions.','The student wants to emphasize a connection between Neris’s scientific training and her artistic work. Which choice most effectively uses relevant information from the notes?','Botanist-turned-illustrator Eda Neris used branching diagrams to represent relationships among the characters in a folktale collection.',['Eda Neris illustrated a folktale collection containing stories from six regions.','Before illustrating folktales, Eda Neris trained as a botanist.','Relationships among characters appear in the illustrations accompanying the collection.'],'The correct choice connects the scientific background to the diagrammatic artistic technique. Merely stating the chronology does not explain the connection as effectively.')
synthesis('hard','A student is researching a fictional mechanical model and has taken these notes:\n\n- A handle turns a large drum.\n- A belt connects the drum to a smaller spool.\n- One full turn of the drum makes the spool turn three times.\n- Demonstrators sometimes count drum turns and sometimes spool turns.','The student wants to explain why two reported turn counts could differ without contradicting each other. Which choice most effectively uses relevant information from the notes?','Counts can differ because a single drum rotation corresponds to three spool rotations, so the reports may be counting different components.',['The model’s handle turns a drum connected by a belt to a spool.','The spool is smaller than the drum in the mechanical model.','Demonstrators use the model to count rotations during a presentation.'],'The correct choice identifies both the different counting units and their relationship. The other facts do not resolve the apparent discrepancy.')
synthesis('medium','A student is researching two fictional performances and has taken these notes:\n\n- Mira’s version of a song keeps the original melody.\n- Mira varies its tempo in response to the dancers.\n- Navo’s version also keeps the original melody.\n- Navo uses the same tempo throughout each performance.','The student wants to contrast how the two versions handle tempo. Which choice most effectively uses relevant information from the notes?','Mira adjusts the tempo to the dancers, whereas Navo maintains a constant tempo throughout a performance.',['Both Mira and Navo preserve the song’s original melody.','The song is performed in versions associated with Mira and Navo.','Mira’s version responds to dancers while preserving the original melody.'],'The correct choice compares both tempo policies directly. The shared melody and a statement about Mira alone do not supply the full contrast.')
synthesis('hard','A student is researching a fictional language project and has taken these notes:\n\n- Volunteers recorded words used in three neighboring valleys.\n- A few words had the same pronunciation but different meanings in different valleys.\n- The project marks each recording with its valley of origin.\n- Recordings were made over two summers.','The student wants to explain the usefulness of the origin labels. Which choice most effectively uses relevant information from the notes?','Because an identical pronunciation can have different meanings across the valleys, origin labels help users interpret a recording in its local context.',['The volunteers made recordings over two summers in three neighboring valleys.','The project includes words that volunteers heard in different locations.','Every recording is marked with a valley, and some words sound alike.'],'The correct choice connects the labels to the interpretive problem they address. Listing both facts without explaining their relationship is less effective.')
synthesis('medium','A student is researching a fictional woven sculpture and has taken these notes:\n\n- The sculpture contains a rigid outer ring and flexible inner cords.\n- The ring keeps the sculpture’s outline stable.\n- The cords move when visitors walk nearby.\n- The artist calls the sculpture “Held Motion.”','The student wants to explain how the sculpture combines stability and movement. Which choice most effectively uses relevant information from the notes?','A rigid ring preserves the sculpture’s outline while flexible cords move in response to nearby visitors.',['The artist named the woven sculpture “Held Motion.”','Visitors can walk near a sculpture made with a ring and cords.','The sculpture’s outer ring is rigid, giving it a stable outline.'],'The correct choice connects both structures to their different functions. The other choices omit the mechanism for stability, movement, or both.')
synthesis('hard','A student is researching a fictional poetry edition and has taken these notes:\n\n- The edition prints each poem beside an earlier draft.\n- Some drafts use a different speaker from the final poem.\n- Notes identify where changes in the speaker alter who can know particular events.\n- The edition includes eighteen poems.','The student wants to describe an interpretive use of comparing the drafts with the final poems. Which choice most effectively uses relevant information from the notes?','Comparing versions can reveal how changing the speaker changes the knowledge available within a poem.',['The edition contains eighteen poems printed beside earlier drafts.','Some earlier drafts and final poems have different speakers.','Readers can find poems and explanatory notes together in the edition.'],'The correct choice explains what the comparison can reveal. The alternatives describe contents or a difference without stating its interpretive significance.')

assert.equal(readingFresh.length,64)
const counts={}
for(const row of readingFresh)counts[row.skill]=(counts[row.skill]??0)+1
assert.equal(Object.keys(counts).length,8)
for(const count of Object.values(counts))assert.equal(count,8)
